package dev.hackuniversity.roombook.rooms;

import java.util.List;
import java.util.Map;

import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

@RestController
@RequestMapping("/v1/rooms")
public class RoomController {

    public record Room(long id, String name, String building, int capacity, List<String> amenities) {}

    private static final Map<Long, Room> ROOMS = Map.of(
            1L, new Room(1, "Turing", "main-library", 6, List.of("whiteboard", "screen")),
            2L, new Room(2, "Lovelace", "main-library", 4, List.of("whiteboard")),
            3L, new Room(3, "Hopper", "science-library", 8, List.of("screen", "video-call")));

    @GetMapping("/{roomId}")
    public ResponseEntity<Room> getRoom(@PathVariable long roomId) {
        Room room = ROOMS.get(roomId);
        if (room == null) {
            return ResponseEntity.notFound().build();
        }
        return ResponseEntity.ok(room);
    }
}
